"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[732],{76342:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"MaterialHudController","desc":"Top-right Materials HUD for the server-wide material pool (Wood, Metal,\\nEnergy). Builds its own\\nScreenGui in code (mockup art; swap for a Studio-authored GUI later). The\\npanel stays hidden and slides down when the pool gains material (any player,\\nshred or research refund), on `MaterialHudConfig.TOGGLE_KEY`, or on a tap of\\nthe touch-only pull tab; it slides back up after `HIDE_DELAY` quiet seconds.\\n\\nGains whose origin is on screen (within `MAX_EFFECT_DISTANCE`) play a\\nLEGO-stud style effect: local Handle clones arc out of the station, rest,\\nthen fly as 2D icons into their HUD row, ticking the counter up on arrival.\\nOff-screen gains roll the counter up instead. Energy has no\\n`CraftingMaterials` template, so its pieces skip the 3D arc and fly as 2D\\nicons straight from the grab point.\\n\\nDisplayed value = server total \u2212 value still in flight, so spends and\\noverlapping gains always settle on the exact server total.","realm":["Client"],"source":{"line":23,"path":"src/StarterPlayer/StarterPlayerScripts/MaterialHudController.client.luau"}}')}}]);